function zigzagInPlace(nums: number[]): void {
  const n = nums.length;
  const s = [...nums].sort((a, b) => a - b);
  const m = (n + 1) >> 1;
  for (let i = 0; i < n; i++) {
    nums[i] = i % 2 === 0 ? s[m - 1 - i / 2] : s[n - 1 - (i - 1) / 2];
  }
}

