function zigzagInPlace(nums: number[]): void {
  const count = new Array(5001).fill(0);
  for (const x of nums) count[x]++;
  let v = 5000;
  const take = (): number => {
    while (count[v] === 0) v--;
    count[v]--;
    return v;
  };
  for (let i = 1; i < nums.length; i += 2) nums[i] = take();
  for (let i = 0; i < nums.length; i += 2) nums[i] = take();
}

